def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify solid divider rows and columns.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, dividers):
        parts = []
        start = 0
        for d in dividers:
            if start < d:
                parts.append((start, d))
            start = d + 1
        if start < size:
            parts.append((start, size))
        return parts

    rs = segments(h, divider_rows)
    cs = segments(w, divider_cols)

    # Select the segment containing the richest pattern, ignoring its
    # most common (background) color when counting pattern cells.
    best = None
    best_score = -1
    for r0, r1 in rs:
        for c0, c1 in cs:
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
            bg = max(counts, key=counts.get)
            score = sum(n for color, n in counts.items() if color != bg)
            if score > best_score:
                best_score = score
                best = (r0, r1, c0, c1)

    r0, r1, c0, c1 = best
    th, tw = r1 - r0, c1 - c0
    out = [row[:] for row in grid]
    for r in range(h):
        if r in divider_rows:
            continue
        for c in range(w):
            if c in divider_cols:
                continue
            out[r][c] = grid[r0 + (r - r0) % th][c0 + (c - c0) % tw]
    return out
