                for c in range(c0, c1):
                    value = grid[r][c]
                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            score = sum(n for value, n in counts.items() if value != background)
            if score > best:
                best = score
                source = (r0, r1, c0, c1)

    r0, r1, c0, c1 = source
    th, tw = r1 - r0, c1 - c0
